package com.termux.app.workspace;
import android.app.*;import android.graphics.*;import android.view.*;import android.widget.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28,application=Application.class)
public class WorkspaceActivityRouteTest {
 @Test public void disabledStopCannotInterruptAndDoesNotChangeItsDimensions(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);final int[] calls={0};b.setOnClickListener(v->{if(b.isEnabled())calls[0]++;});b.layout(0,0,44,44);b.performClick();assertEquals(0,calls[0]);b.setEnabled(true);b.performClick();assertEquals(1,calls[0]);assertEquals(44,b.getWidth());assertEquals(Button.class.getName(),b.getAccessibilityClassName());}
 @Test public void fourGlyphsAndEveryStateUseSameHitArea(){Activity a=Robolectric.buildActivity(Activity.class).setup().get();AgentStopButton b=new AgentStopButton(a);b.layout(0,0,44,44);Canvas c=new Canvas(Bitmap.createBitmap(44,44,Bitmap.Config.ARGB_8888));for(String agent:new String[]{"Codex","Claude","Gemini","OpenCode"})for(AgentIndicatorState.State state:AgentIndicatorState.State.values()){b.indicator(agent,state);b.frame(3150000000L,0);b.onDraw(c);assertEquals(state,b.state());assertEquals(44,b.getWidth());assertEquals(44,b.getHeight());assertEquals(state!=AgentIndicatorState.State.IDLE&&state!=AgentIndicatorState.State.ERROR,b.animated());}}
 @Test public void frameCadenceTargets60AcrossDifferentDisplayRefreshRates(){for(int hz:new int[]{60,90,120,144}){WorkspaceActivityLine.FrameCadence clock=new WorkspaceActivityLine.FrameCadence();int redraws=0;for(int frame=0;frame<hz*10;frame++)if(clock.due(1000000000L+Math.round(frame*1000000000d/hz)))redraws++;assertTrue(Math.abs(redraws-600)<=1);}}
 @Test public void missedFramesResumeWithoutBurstAndResetStartsImmediately(){WorkspaceActivityLine.FrameCadence clock=new WorkspaceActivityLine.FrameCadence();assertTrue(clock.due(1000000000L));assertFalse(clock.due(1000000000L));assertTrue(clock.due(5000000000L));assertFalse(clock.due(5000000000L));clock.reset();assertTrue(clock.due(5000000000L));}
 @Test public void orbitAndSixAsymmetricContactsStayInsideButtonAndHaveNoSeam(){for(float r:new float[]{7,15.5f,32}){AgentStopButton.OrbitRoute orbit=new AgentStopButton.OrbitRoute(r);float[] points=orbit.path.approximate(.005f);assertEquals(6,orbit.hits.length);assertTrue(orbit.insideStart<orbit.hits[0]);assertTrue(orbit.insideEnd>orbit.hits[5]);float previous=orbit.insideStart;for(float hit:orbit.hits){assertTrue(hit>previous);assertTrue(orbit.strike(hit,r)>.9f);previous=hit;}for(int i=0;i<points.length;i+=3)assertTrue(Math.hypot(points[i+1],points[i+2])<=r*1.01+.03);assertEquals(points[1],points[points.length-2],.01);assertEquals(points[2],points[points.length-1],.01);assertFalse(orbit.measure.nextContour());assertTrue(orbit.distance(1000)<orbit.distance(1000000));}}
 @Test public void agentNeverAttachesOuterRouteAndOrdinarySessionsKeepLine(){Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a);WorkspaceActivityLine line=new WorkspaceActivityLine(a,null);AgentStopButton b=new AgentStopButton(a);host.addView(line,new FrameLayout.LayoutParams(300,2));host.addView(b,new FrameLayout.LayoutParams(44,44));a.setContentView(host);line.layout(0,0,300,2);b.layout(200,10,244,54);Canvas c=new Canvas(Bitmap.createBitmap(300,60,Bitmap.Config.ARGB_8888));line.stopTarget(b);b.indicator("Codex",AgentIndicatorState.State.WORKING);line.working(true);line.onDraw(c);assertFalse(line.routing());line.stopTarget(null);line.onDraw(c);assertTrue(line.working());line.working(false);assertFalse(line.working());host.removeView(line);}
 @Test public void disabledSystemAnimationsDoNotScheduleAFrameLoop()throws Exception{java.lang.reflect.Method scale=android.animation.ValueAnimator.class.getDeclaredMethod("setDurationScale",float.class);scale.setAccessible(true);scale.invoke(null,0f);Activity a=Robolectric.buildActivity(Activity.class).setup().visible().get();FrameLayout host=new FrameLayout(a);WorkspaceActivityLine line=new WorkspaceActivityLine(a,null);AgentStopButton b=new AgentStopButton(a);host.addView(line,new FrameLayout.LayoutParams(300,2));host.addView(b,new FrameLayout.LayoutParams(44,44));a.setContentView(host);line.layout(0,0,300,2);line.stopTarget(b);b.indicator("Gemini",AgentIndicatorState.State.WORKING);try{line.working(true);line.onDraw(new Canvas(Bitmap.createBitmap(300,2,Bitmap.Config.ARGB_8888)));java.lang.reflect.Field frame=WorkspaceActivityLine.class.getDeclaredField("framePending");frame.setAccessible(true);assertFalse(frame.getBoolean(line));}finally{line.working(false);scale.invoke(null,1f);}}
}
